    value >>= 16;
    bit += 16;
  }
  if ((value & UINT32_C(0x000000FF)) == 0) {
    value >>= 8;
    bit += 8;
  }
  if ((value & UINT32_C(0x0000000F)) == 0) {
    value >>= 4;
    bit += 4;
  }
  if ((value & UINT32_C(0x00000003)) == 0) {
    value >>= 2;
    bit += 2;
  }
  if ((value & UINT32_C(0x00000001)) == 0) {
